package nexusbench

import (
	"bytes"
	"context"
	"os/exec"
)

// Runner runs one kubectl command. args are the arguments after "kubectl" and
// carry no --context: the runner adds it. stdin is sent to the command when it
// is not empty. Both streams are returned even on failure, because the stderr
// of a failed call is what classifyKubectl reads.
type Runner interface {
	Run(ctx context.Context, stdin []byte, args ...string) (stdout, stderr []byte, err error)
}

// execRunner runs the kubectl found on PATH against one context.
type execRunner struct {
	path    string
	context string
}

// NewExecRunner finds kubectl on PATH and returns a Runner that passes
// "--context <kubeContext>" to every call. It fails with a KubectlMissing
// BenchError when kubectl is not installed. This is the one place of the
// package that starts a process.
func NewExecRunner(kubeContext string) (Runner, error) {
	path, err := exec.LookPath("kubectl")
	if err != nil {
		return nil, &BenchError{
			Kind:  KubectlMissing,
			Cause: "kubectl was not found on PATH",
			Check: "run `mise install` to get kubectl, then `kubectl version --client`",
			Err:   err,
		}
	}
	return &execRunner{path: path, context: kubeContext}, nil
}

// Run implements Runner.
func (r *execRunner) Run(ctx context.Context, stdin []byte, args ...string) (stdout, stderr []byte, err error) {
	full := append([]string{"--context", r.context}, args...)
	cmd := exec.CommandContext(ctx, r.path, full...) //nolint:gosec // the binary is the kubectl found on PATH and the arguments are built by this package from validated parameters
	if len(stdin) > 0 {
		cmd.Stdin = bytes.NewReader(stdin)
	}
	var out, errOut bytes.Buffer
	cmd.Stdout, cmd.Stderr = &out, &errOut
	err = cmd.Run()
	return out.Bytes(), errOut.Bytes(), err
}
package nexusbench

import (
	"context"
	"io"
	"net/http"
	"strings"
	"time"
)

// probeTimeout bounds one probe, connection included: the wait asks again at
// its next round, so a short one is enough and a silent host costs little.
const probeTimeout = 5 * time.Second

// probeOp names the probe in its errors.
const probeOp = "probe the Nexus status"

// Prober tells whether a Nexus answers on baseURL ("http://host:port").
type Prober interface {
	// Ready returns nil when GET <baseURL>/service/rest/v1/status answers 200,
	// and an error otherwise, whatever the reason.
	Ready(ctx context.Context, baseURL string) error
}

// httpProber is the Prober of the command.
type httpProber struct {
	http *http.Client
}

// NewProber returns the Prober that asks the instance over HTTP. It sends one
// unauthenticated GET, follows no redirection, goes through no proxy, and never
// reads or reports the body of the answer.
func NewProber() Prober {
	transport := http.DefaultTransport.(*http.Transport).Clone()
	transport.Proxy = nil
	// One probe per round: keeping the connection alive would only hold a socket
	// open on a pod that may be restarting.
	transport.DisableKeepAlives = true
	return &httpProber{http: &http.Client{
		Timeout:       probeTimeout,
		Transport:     transport,
		CheckRedirect: func(*http.Request, []*http.Request) error { return http.ErrUseLastResponse },
	}}
}

// Ready implements Prober. The error is a *transportError (no answer) or an
// *APIError (an answer other than 200); neither prints the URL or the body.
func (pr *httpProber) Ready(ctx context.Context, baseURL string) error {
	target := strings.TrimRight(baseURL, "/") + restStatusPath
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, target, nil)
	if err != nil {
		return &transportError{Op: probeOp, Err: err}
	}
	resp, err := pr.http.Do(req)
	if err != nil {
		return &transportError{Op: probeOp, Err: err}
	}
	defer func() { _ = resp.Body.Close() }()
	_, _ = io.Copy(io.Discard, io.LimitReader(resp.Body, drainBytes))
	if resp.StatusCode != http.StatusOK {
		return &APIError{Op: probeOp, Status: resp.StatusCode}
	}
	return nil
}
