	Op     string
	Status int
}

// Error returns "<Op>: HTTP <status> <text>".
func (e *APIError) Error() string {
	return strings.TrimSpace(fmt.Sprintf("%s: HTTP %d %s", e.Op, e.Status, http.StatusText(e.Status)))
