// expect sends r and turns a status outside 2xx into an *APIError.
func (c *client) expect(ctx context.Context, r request) (response, error) {
	resp, err := c.do(ctx, r)
	if err != nil {
		return resp, err
	}
	if resp.status < 200 || resp.status > 299 {
		return resp, &APIError{Op: r.op, Status: resp.status}
	}
	return resp, nil
}

// get reads path and decodes the JSON answer into out (nil: not decoded). A 404
// is found == false without an error.
func (c *client) get(ctx context.Context, op, path string, query url.Values, out any) (found bool, err error) {
	resp, err := c.do(ctx, request{op: op, method: http.MethodGet, path: path, query: query})
	if err != nil {
		return false, err
	}
	switch {
	case resp.status == http.StatusNotFound:
		return false, nil
	case resp.status < 200 || resp.status > 299:
		return false, &APIError{Op: op, Status: resp.status}
	}
	if out == nil {
		return true, nil
	}
	if err := json.Unmarshal(resp.body, out); err != nil {
		return false, &decodeError{Op: op, Err: err}
	}
	return true, nil
}

// read is get for an object that has to exist: a 404 is an *APIError.
func (c *client) read(ctx context.Context, op, path string, query url.Values, out any) error {
	found, err := c.get(ctx, op, path, query, out)
	if err != nil {
		return err
	}
	if !found {
		return &APIError{Op: op, Status: http.StatusNotFound}
	}
	return nil
}

// write sends payload as JSON with method and expects a 2xx.
func (c *client) write(ctx context.Context, op, method, path string, payload any) error {
	data, err := json.Marshal(payload)
	if err != nil {
		return &decodeError{Op: op, Err: err}
	}
	_, err = c.expect(ctx, request{op: op, method: method, path: path, contentType: "application/json", body: data})
	return err
}
package nexusbench

import (
	"context"
	"time"
)

// Clock is the time the waits of the bench read and spend. Tests swap it for a
// fake that never waits, so no test sleeps for real.
type Clock interface {
	// Now returns the current time.
	Now() time.Time
	// Sleep waits for d, or until ctx is done. It returns ctx.Err() when ctx is
	// done, before sleeping if it already was, and nil after the whole wait. A
	// duration of zero or less returns at once (after the ctx check).
	Sleep(ctx context.Context, d time.Duration) error
}

// realClock is the Clock of the command: the wall clock.
type realClock struct{}

// NewClock returns the real clock.
func NewClock() Clock { return realClock{} }

// Now implements Clock.
func (realClock) Now() time.Time { return time.Now() }

// Sleep implements Clock.
func (realClock) Sleep(ctx context.Context, d time.Duration) error {
	if err := ctx.Err(); err != nil {
		return err
	}
	if d <= 0 {
		return nil
	}
	timer := time.NewTimer(d)
	defer timer.Stop()
	select {
	case <-ctx.Done():
		return ctx.Err()
	case <-timer.C:
		return nil
	}
}
// Package nexusbench is the disposable Nexus Community bench (DEVDESK-504,
// NX-01): a single Nexus pod in a dedicated namespace of the k0s cluster,
// deployed, provisioned over its REST API and destroyed with one command, so
// that the registry measurements of the NX stories run against a real Nexus.
//
// The package is a development tool, not product code: the dk binary does not
// import it, and none of its tests run against a cluster unless
// DEVDESK_NEXUS_BENCH=1 is set.
//
// This file holds nothing but documentation. params.go turns defaults,
// environment variables and flags into a validated Params value; kubectl.go is
