// No bench task is part of, or reachable from, a task the standard checks run.
func TestMiseNoStandardTaskReachesTheBench(t *testing.T) {
	f := loadMise(t)
	for _, root := range []string{"ci", "check", "test", "test-race"} {
		t.Run(root, func(t *testing.T) {
			if _, ok := f.task(root); !ok {
				t.Fatalf("mise.toml has no task %q", root)
			}
			seen := map[string]bool{}
			queue := []string{root}
			for len(queue) > 0 {
				name := queue[0]
				queue = queue[1:]
				if seen[name] {
					continue
				}
				seen[name] = true
				if strings.HasPrefix(name, miseBenchPrefix) {
					t.Errorf("%s reaches the bench task %s", root, name)
					continue
				}
				keys, _ := f.task(name)
				for k, v := range keys {
					if strings.Contains(v, miseBenchPrefix) {
						t.Errorf("task %s (reached from %s) mentions %q in %s", name, root, miseBenchPrefix, k)
					}
				}
				queue = append(queue, miseRefs(keys)...)
			}
		})
	}
}

// kubectl is declared once, on the bench tasks, or once, globally. Declared
// globally it would be installed for every CI run; the tasks are the better
// place, so a global declaration next to complete task declarations is refused.
func TestMiseKubectlIsDeclaredOnTheBenchTasks(t *testing.T) {
	f := loadMise(t)
	names := []string{miseBenchPrefix + ":test"}
	for _, sub := range miseBenchSubcommands {
		names = append(names, miseBenchPrefix+":"+sub)
	}
	var with, without []string
	for _, name := range names {
		task, ok := f.task(name)
		if !ok {
			t.Errorf("mise.toml has no task %q", name)
			continue
		}
		if strings.Contains(task["tools"], "kubectl") {
			with = append(with, name)
		} else {
			without = append(without, name)
		}
	}
	_, globally := f["tools"]["kubectl"]
	switch {
	case len(with) == len(names) && globally:
		t.Error("kubectl is declared in the global [tools] and on every bench task: keep the tasks, drop the global one (it would be installed for every CI run)")
	case len(with) == 0 && !globally:
		t.Error("kubectl is declared nowhere: add it to the `tools` of each nexus-bench:* task (or to [tools])")
	case len(with) > 0 && len(without) > 0:
		t.Errorf("kubectl is declared on %v but not on %v: declare it on all six or on none", with, without)
	}
}
